function slowSquareSum(n) {
  var sum = 0;
  for (var i = 0; i < n; i++) {
    sum += i * i;
  }
  return sum;
}
var start = performance.now();
var result = slowSquareSum(100000);
var end = performance.now();
console.log(result);
console.log(typeof (end - start));
console.log(end - start >= 0);

