'use strict';
function countdown(n) {
  if (n <= 0) return 'done';
  return countdown(n - 1); // 尾呼叫位置
}
try {
  console.log(countdown(1000000));
} catch (e) {
  console.log('crashed with', e.constructor.name);
}

